<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/database.php';
if($_SERVER['REQUEST_METHOD']==='GET'){ $status=$_GET['status']??''; if(in_array($status,['ordered','making','done'],true)){$s=db()->prepare("SELECT * FROM orders WHERE status=? ORDER BY id DESC LIMIT 50");$s->execute([$status]);}else{$s=db()->query("SELECT * FROM orders WHERE status IN ('ordered','making') ORDER BY id ASC LIMIT 100");}$orders=$s->fetchAll();foreach($orders as &$o){$s=db()->prepare("SELECT * FROM order_items WHERE order_id=? ORDER BY id");$s->execute([$o['id']]);$o['items']=$s->fetchAll();}echo json_encode(['success'=>true,'orders'=>$orders]);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ $data=json_decode(file_get_contents('php://input'),true);$items=$data['items']??[];if(!$items){http_response_code(400);echo json_encode(['success'=>false,'error'=>'Order is empty.']);exit;}$pdo=db();$pdo->beginTransaction();try{$next=(int)$pdo->query("SELECT COALESCE(MAX(order_number),1000)+1 FROM orders")->fetchColumn();$total=0;foreach($items as $i)$total+=(float)$i['price']*(int)$i['quantity'];$s=$pdo->prepare("INSERT INTO orders(order_number,total) VALUES(?,?)");$s->execute([$next,$total]);$orderId=$pdo->lastInsertId();$s=$pdo->prepare("INSERT INTO order_items(order_id,drink_id,drink_name,milk_type,price,quantity) VALUES(?,?,?,?,?,?)");foreach($items as $i)$s->execute([$orderId,$i['id']??null,$i['name'],$i['milk']??null,$i['price'],$i['quantity']]);$pdo->commit();echo json_encode(['success'=>true,'order_number'=>$next]);}catch(Throwable $e){$pdo->rollBack();http_response_code(500);echo json_encode(['success'=>false,'error'=>'Database error.']);}exit;}
http_response_code(405);echo json_encode(['success'=>false,'error'=>'Method not allowed']);
